import heapq


def dependency_solver(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best_install = None

    def acyclic(edges):
        active, done = set(), set()

        def visit(node):
            if node in active:
                return False
            if node in done:
                return True
            active.add(node)
            if any(not visit(other) for other in edges.get(node, ())):
                return False
            active.remove(node)
            done.add(node)
            return True

        return all(visit(node) for node in edges)

    def search(chosen, constraints, edges):
        nonlocal best_vector, best_install
        pending = [name for name in constraints if name not in chosen]
        if not pending:
            if not acyclic(edges):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if (best_vector is None or
                    (vector > best_vector if maximize else vector < best_vector)):
                best_vector = vector
                best_install = dict(chosen)
            return

        name = min(pending)
        low, high = constraints[name]
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_constraints = dict(constraints)
            next_edges = {key: set(value) for key, value in edges.items()}
            next_edges.setdefault(name, set())
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                lo, hi = dep["min"], dep["max"]
                if target in next_constraints:
                    old_lo, old_hi = next_constraints[target]
                    lo, hi = max(lo, old_lo), min(hi, old_hi)
                if lo > hi:
                    valid = False
                    break
                next_constraints[target] = (lo, hi)
                next_edges[name].add(target)
                if target in next_chosen and not lo <= next_chosen[target] <= hi:
                    valid = False
                    break
            if valid:
                search(next_chosen, next_constraints, next_edges)

    search({}, {name: tuple(bounds) for name, bounds in data["roots"].items()}, {})
    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _component_01(data):
    return dependency_solver(data, "ascending", False)


def _component_02(data):
